// TypeScript Version: 4.1

/**
* Computes the squared error loss.
*
* ## Notes
*
* -   The squared error loss is defined as the squared difference of the observed and fitted value.
*
* @param y - true target value
* @param p - predicted value
* @returns squared error loss
*
* @example
* var v = squaredError( -2.0, -1.782 );
* // returns ~0.0238
*
* @example
* var v = squaredError( 0.202, 0.202 );
* // returns 0.0
*
* @example
* var v = squaredError( 1.0, -0.999 );
* // returns ~1.998
*
* @example
* var v = squaredError( -2.4, 0.234 );
* // returns ~3.469
*
* @example
* var v = squaredError( 0.2, 0.532 );
* // returns ~0.0551
*
* @example
* var v = squaredError( -1.811, -0.9 );
* // returns ~0.415
*/
declare function squaredError( y: number, p: number ): number;


// EXPORTS //

export = squaredError;
